@triton.jit
def atan2_same_kernel(
    y_ptr, x_ptr, N, BLOCK: tl.constexpr, LOWDEG: tl.constexpr, NATIVE: tl.constexpr
):
    # Persistent grid-stride loop. A grid-stride form (program 0 processes more
    # than one block) is required on this Ascend/flagtree backend; the
    # single-block-per-program form corrupts the very first block.
    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    for base in range(pid * BLOCK, N, nprog * BLOCK):
        offs = base + tl.arange(0, BLOCK)
        mask = offs < N
        y = tl.load(y_ptr + offs, mask=mask)
        x = tl.load(x_ptr + offs, mask=mask)
        tl.store(y_ptr + offs, _atan2(y, x, LOWDEG, NATIVE), mask=mask)


